import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getRestaurantById, getRestaurantTables, getRestaurantTimeSlots, createReservation } from '../../services/api';

const RestaurantDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [restaurant, setRestaurant] = useState(null);
  const [tables, setTables] = useState([]);
  const [timeSlots, setTimeSlots] = useState([]);
  const [formData, setFormData] = useState({
    table_id: '',
    time_slot_id: '',
    reservation_date: '',
    guest_count: 1,
    special_requests: ''
  });
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    loadData();
  }, [id]);

  const loadData = async () => {
    try {
      const [restaurantRes, tablesRes, timeSlotsRes] = await Promise.all([
        getRestaurantById(id),
        getRestaurantTables(id),
        getRestaurantTimeSlots(id)
      ]);
      setRestaurant(restaurantRes.data);
      setTables(tablesRes.data);
      setTimeSlots(timeSlotsRes.data);
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      await createReservation({
        restaurant_id: parseInt(id),
        ...formData,
        table_id: parseInt(formData.table_id),
        time_slot_id: parseInt(formData.time_slot_id),
        guest_count: parseInt(formData.guest_count)
      });
      alert('Reservation created successfully!');
      navigate('/my-reservations');
    } catch (error) {
      alert(error.response?.data?.error || 'Failed to create reservation');
    } finally {
      setSubmitting(false);
    }
  };

  const getTableIcon = (capacity) => {
    if (capacity <= 2) return '🪑';
    if (capacity <= 4) return '🪑🪑';
    if (capacity <= 6) return '🍽️';
    return '🍽️🍽️';
  };

  if (loading) return <div style={styles.loading}>Loading...</div>;
  if (!restaurant) return <div style={styles.loading}>Restaurant not found</div>;

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <img src={restaurant.image_url || 'https://via.placeholder.com/1200x400'} alt={restaurant.name} style={styles.headerImage} />
        <div style={styles.headerOverlay}>
          <h1 style={styles.title}>{restaurant.name}</h1>
          <p style={styles.cuisine}>{restaurant.cuisine_type}</p>
        </div>
      </div>

      <div style={styles.content}>
        <div style={styles.info}>
          <h2>About</h2>
          <p>{restaurant.description || 'A wonderful dining experience awaits you!'}</p>
          <div style={styles.details}>
            <p><strong>📍 Address:</strong> {restaurant.address}</p>
            <p><strong>📞 Phone:</strong> {restaurant.phone}</p>
            <p><strong>🕒 Hours:</strong> {restaurant.opening_time} - {restaurant.closing_time}</p>
          </div>
        </div>

        <div style={styles.bookingCard}>
          <h2>Make a Reservation</h2>
          <form onSubmit={handleSubmit} style={styles.form}>
            <div style={styles.formGroup}>
              <label style={styles.label}>Date *</label>
              <input
                type="date"
                required
                min={new Date().toISOString().split('T')[0]}
                value={formData.reservation_date}
                onChange={(e) => setFormData({...formData, reservation_date: e.target.value})}
                style={styles.input}
              />
            </div>

            <div style={styles.formGroup}>
              <label style={styles.label}>Time Slot *</label>
              <div style={styles.timeSlotGrid}>
                {timeSlots.map((slot) => (
                  <div
                    key={slot.id}
                    onClick={() => setFormData({...formData, time_slot_id: slot.id})}
                    style={{
                      ...styles.timeSlotCard,
                      ...(formData.time_slot_id === slot.id ? styles.timeSlotCardSelected : {})
                    }}
                  >
                    <div style={styles.timeSlotTime}>🕒 {slot.slot_time}</div>
                    <div style={styles.timeSlotDuration}>{slot.duration_minutes} min</div>
                  </div>
                ))}
              </div>
              {timeSlots.length === 0 && <p style={styles.noData}>No time slots available</p>}
            </div>

            <div style={styles.formGroup}>
              <label style={styles.label}>Select Table *</label>
              <div style={styles.tableGrid}>
                {tables.filter(t => t.is_available).map((table) => (
                  <div
                    key={table.id}
                    onClick={() => setFormData({...formData, table_id: table.id})}
                    style={{
                      ...styles.tableCard,
                      ...(formData.table_id === table.id ? styles.tableCardSelected : {})
                    }}
                  >
                    <div style={styles.tableIcon}>{getTableIcon(table.capacity)}</div>
                    <div style={styles.tableNumber}>Table {table.table_number}</div>
                    <div style={styles.tableCapacity}>
                      <span style={styles.capacityIcon}>👥</span> {table.capacity} seats
                    </div>
                  </div>
                ))}
              </div>
              {tables.filter(t => t.is_available).length === 0 && (
                <p style={styles.noData}>No tables available</p>
              )}
            </div>

            <div style={styles.formGroup}>
              <label style={styles.label}>Number of Guests *</label>
              <input
                type="number"
                required
                min="1"
                value={formData.guest_count}
                onChange={(e) => setFormData({...formData, guest_count: e.target.value})}
                style={styles.input}
              />
            </div>

            <div style={styles.formGroup}>
              <label style={styles.label}>Special Requests</label>
              <textarea
                value={formData.special_requests}
                onChange={(e) => setFormData({...formData, special_requests: e.target.value})}
                style={{...styles.input, minHeight: '80px'}}
                placeholder="Any special requests or dietary requirements..."
              />
            </div>

            <button type="submit" disabled={submitting || !formData.table_id || !formData.time_slot_id} style={styles.submitBtn}>
              {submitting ? 'Booking...' : 'Book Now'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

